insert into public.passages (id, code, skill_id, sat_alignment, grade_band, title, body, status)
values ('f1345895-1a08-51a0-b66e-c084ec184840', 'rg3-text-structure-p01', (select id from public.skills where slug = 'read-g3-text-structure'), null,
        '3-5', $q$From Flower to Honey Jar$q$, $q$Honeybees make honey in a hive. The job takes many steps, and thousands of bees help.

Heading: Step 1, Finding Flowers

First, worker bees fly out of the hive to find flowers. They drink a sweet liquid called nectar. A bee stores the nectar in a special honey stomach.

Heading: Step 2, Back to the Hive

Next, the bee flies home. It passes the nectar to another bee inside the hive. That bee chews the nectar and adds tiny bits from its own body. This begins to change the nectar into honey.

Heading: Step 3, Drying the Honey

Then the bees put the nectar into wax cells. The nectar is still too watery. So the bees fan it with their wings. The moving air dries it out until it turns thick and sticky.

Heading: Step 4, Sealing the Cells

Finally, the bees cover each full cell with a lid of wax. The honey stays fresh inside until the bees need food in winter.

Picture caption: A beekeeper in a net hat lifts a wooden frame covered with wax cells.

Sidebar, Fun Fact: One bee makes only about one twelfth of a teaspoon of honey in its whole life.$q$, 'draft')
